window.docContents[191].resolve({"/UD-IV___-abstraction/Function-and-program/#Core-C______--UD-IV___-abstraction--Function-and-program":{"contents":"A function is well typed when its body is, under the context of its parameters and its return type.\n\nA program is a list of functions with distinct names and a function int main(). The initial store is empty, because there are no global variables, and the result is the value of main().\n\n","context":"Core C++\u0009UD IV, abstraction","header":"5.5. Function and program","id":"/UD-IV___-abstraction/Function-and-program/#Core-C______--UD-IV___-abstraction--Function-and-program"}});